practice.solution:
#!/usr/bin/env bash
set -eEuo pipefail

on_exit() {
  local rc=$?
  echo "exit status: $rc"
  exit "$rc"
}
trap on_exit EXIT
trap 'echo "FAILED at line $LINENO: $BASH_COMMAND" >&2' ERR

package() {
  mkdir -p release
  cp build/index.html build/app.js build/app.css release/
  cp build/VERSION release/
}

package
echo "packaged $(< release/VERSION)"
